class Solution {
    fun secondGreaterElement(nums:IntArray):IntArray{
        val answer=IntArray(nums.size){
            -1
        };
        val first=java.util.ArrayDeque<Int>();
        val second=java.util.ArrayDeque<Int>();
        for(i in nums.indices){
            while(second.isNotEmpty()&&nums[second.peek()]<nums[i])answer[second.pop()]=nums[i];
            val moved=mutableListOf<Int>();
            while(first.isNotEmpty()&&nums[first.peek()]<nums[i])moved.add(first.pop());
            for(j in moved.lastIndex downTo 0)second.push(moved[j]);
            first.push(i)
        };
        return answer
    }
}

